const allFabricIds: FabricBehaviourId[] = [
  'sheer-voile',
  'lightweight-woven',
  'linen-look-medium',
  'medium-woven',
  'silk-look',
  'chenille',
  'velvet',
  'jacquard',
  'blackout-coated',
];

function affinity(values: Partial<Record<FabricBehaviourId, number>>) {
  return Object.fromEntries(allFabricIds.map((id) => [id, values[id] ?? 0.5])) as Record<
    FabricBehaviourId,
    number
  >;
}

