const colour = (
  id: string,
  displayName: string,
  family: string,
  hueDegrees: number,
  lightness: number,
  saturation: number,
  temperature: ColourArchetype['temperature'],
  undertones: string[],
  neutrality: ColourArchetype['neutrality'],
  visualWeight: number,
  association: string,
  context: string,
  lightingSensitivity: string[],
): ColourArchetype => ({
  id,
  displayName,
  family,
  hueDegrees,
  lightness,
  saturation,
  temperature,
  undertones,
  neutrality,
  visualWeight,
  atmosphericAssociations: [{ label: association, strength: 0.55, context }],
  lightingSensitivity,
  basis: 'design-hypothesis',
});

